package com.procurement.rfq.controller;import com.procurement.common.response.*;import com.procurement.rfq.dto.response.*;import com.procurement.rfq.service.*;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/rfq-vendors")public class RfqVendorController{private final RfqVendorService service;public RfqVendorController(RfqVendorService s){service=s;}@GetMapping("/search")public ApiResponse<PageResponse<RfqVendorResponse>>search(@RequestParam(required=false)Long rfqId,@RequestParam(required=false)Long vendorId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="invitationDate")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(service.search(rfqId,vendorId,PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort))));}}
